def rects(g):
    bg=g[0][0]
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                c=g[i][j]; i2=i
                while i2<H and g[i2][j]==c: i2+=1
                j2=j
                while j2<W and g[i][j2]==c: j2+=1
                ok=all(g[a][b]==c for a in range(i,i2) for b in (j,j2-1)) and all(g[i2-1][b]==c for b in range(j,j2))
                if ok:
                    out.append((i,i2,j,j2,c)); 
                    for a in range(i,i2):
                        for b in range(j,j2): seen.add((a,b))
                else:
                    seen.add((i,j))
    return out

def f(g):
    g=[r[:] for r in g]
    for i,i2,j,j2,c in rects(g):
        fill=7 if (i2-i)*(j2-j)%2 else 2
        for a in range(i+1,i2-1):
            for b in range(j+1,j2-1):
                g[a][b]=fill
    return g

